function setCurrentTab(path: string) {
    if (path.endsWith('userinfo')) {
        currentIndex.value = 0
    } else if (path.endsWith('recharge')) {
        currentIndex.value = 1
    } else if (path.endsWith('bag')) {
        currentIndex.value = 2
    } else if (path.endsWith('balance')) {
        currentIndex.value = 7
        isShowChild.value = true
    } else if (path.endsWith('goods')) {
        currentIndex.value = 8
        isShowChild.value = true
    } else if (path.endsWith('share')) {
        currentIndex.value = 4
    } else if (path.endsWith('message')) {
        currentIndex.value = 5
    }
}

function changeTab(index: number) {
    let path = ""
    switch (index) {
        case 0:
            path = "userinfo"
            break;
        case 1:
            path = "recharge"
            break;
        case 2:
            path = "bag"
            break;
        case 3:
            //显示child
            isShowChild.value = !isShowChild.value
            return
        case 4:
            path = "share"
            break;
        case 5:
            path = "message"
            break;
        case 7:
            path = 'balance'
            break;
        case 8:
            path = 'goods'
            break;
    }
    router.push({
        path: path
    })
}

function logout() {
    showOpDialog(function () {
        //清空用户数据
        userStore.logout()
        router.replace({
            name: 'home'
        })
    }, {
        text: t('mine.confirmLogout'),
    })
}

